  var BEN_SITE = sc("---", "- hosts: all", "  become: yes", "  tasks:", "    - apt: name=nginx state=latest", "      when: \"'web' in group_names\"", "    - shell: useradd -m maya; useradd -m ben", "    - shell: ufw allow 22 && ufw --force enable", "    - copy:", "        content: \"server { listen 80; server_name staging.kestrel.internal; root /var/www/html; }\"", "        dest: /etc/nginx/sites-available/default", "      when: \"'web' in group_names\"");
