  var LINTY = sc("---", "- name: notes app", "  hosts: web", "  become: yes", "  tasks:", "    - apt: name=git state=latest", "    - name: Get the release", "      shell: curl -s https://releases.kestrel.io/notes.tar.gz | tar xz -C /opt", "    - name: Config", "      template:", "        src: notes.conf.j2", "        dest: /etc/notes.conf");
