  function lastCheckov(r) { return H.events(r, "checkov").filter(function (e) { return /infra\/web$/.test(e.dir); }).slice(-1)[0]; }
  function scanNow(r) { var fs = { read: function (p) { return r.read(p); }, list: function (d) { var n = window.Dk.fsNode(r.sys, d); return n && n.type === "d" ? keys(n.children).sort() : null; }, isDir: function (d) { var n = window.Dk.fsNode(r.sys, d); return !!n && n.type === "d"; } }; try { return IAC.checkovScan(fs, HOME + "/infra/web", {}).results; } catch (e) { return []; } }
  function status(res, id, type) { var x = res.filter(function (y) { return y.id === id && (!type || y.resource.indexOf(type) === 0); })[0]; return x ? x.result : null; }
  LABS.push({
    id: "dev-308", n: 8, module: 3, ticket: "DEV-308", xp: 190, tool: "Checkov",
    title: "Scanning IaC",
    topic: "Checkov on Terraform, fixing vs suppressing with a reason, ansible-lint",
    from: DEV,
    story: "<p>Before anything in <code>~/infra/web</code> is applied, Dev wants it scanned: the config opens SSH to the world, leaves the metadata service on v1, doesn't encrypt the disk, and the uploads bucket has none of the protections from DEV-303. Run <b>Checkov</b>, fix what matters, suppress what doesn't apply <b>with a written reason</b>, and get <b>zero failed checks</b>. Then apply it. The Ansible playbook <code>~/ansible/notes.yml</code> gets the same treatment from <code>ansible-lint</code>.</p>",
    learn:
      "<h3>Policy as code</h3><p>Scanners check IaC against hundreds of rules before anything exists, so a public bucket or an open port is caught in review instead of in an incident. <b>Checkov</b> covers Terraform, CloudFormation, Kubernetes, Dockerfiles and more:</p>" + ex("checkov -d .") + ex("checkov -d . --compact --quiet") +
      code("Check: CKV_AWS_24: \"Ensure no security groups allow ingress from 0.0.0.0:0 to port 22\"\n\tFAILED for resource: aws_security_group.web\n\tFile: /main.tf:16-41") +
      "<p><code>--compact</code> hides the code snippets, <code>--quiet</code> shows only failures, <code>--check ID</code> runs selected checks. The exit code is 1 when anything fails, which is what makes it a pipeline gate.</p>" +
      "<h3>Fix or suppress</h3><p>Fix the real problems. Some checks don't apply to a given resource (a public web server <i>should</i> accept HTTP from anywhere): suppress those inside the resource with a reason a reviewer can judge:</p>" + code("resource \"aws_security_group\" \"web\" {\n  #checkov:skip=CKV_AWS_260:This is the public web server: HTTP from anywhere is its job\n  ...") +
      "<p>A suppression without a reason is a finding you hid. Reviewers should be able to disagree with your reason.</p>" +
      "<h3>ansible-lint</h3>" + ex("ansible-lint") + "<p>It flags unnamed tasks, short module names, <code>yes</code>/<code>no</code> booleans, <code>state: latest</code>, shell commands where a module exists, files without an explicit mode, and pipes without <code>pipefail</code>. Fix rather than <code># noqa</code>.</p>",
    system: WORLD_308,
    starter: "cd ~/infra/web",
    objectives: [
      { id: "scan", text: "Scan <code>~/infra/web</code> with Checkov and read the failures.", hints: ["checkov -d . (or --compact)"],
        check: function (r) { return ran(r, /^\s*checkov\b/, function (e) { return /Failed checks: [1-9]/.test(out(e)); }) ? true : "Run checkov -d . in ~/infra/web."; } },
      { id: "server", text: "Fix the server and its firewall: SSH only from the office (<code>203.0.113.0/24</code>), IMDSv2 required, encrypted root disk, detailed monitoring, rule descriptions, and egress limited to HTTPS.", hints: ["CKV_AWS_24, CKV_AWS_79, CKV_AWS_8, CKV_AWS_126, CKV_AWS_382: cidr_blocks, metadata_options, root_block_device, monitoring = true, an egress rule for 443 only."],
        check: function (r) { var res = scanNow(r); var need = [["CKV_AWS_24", "aws_security_group"], ["CKV_AWS_79", "aws_instance"], ["CKV_AWS_8", "aws_instance"], ["CKV_AWS_126", "aws_instance"], ["CKV_AWS_382", "aws_security_group"]].filter(function (x) { return status(res, x[0], x[1]) !== "PASSED"; }); return need.length ? "Still failing (or skipped): " + need.map(function (x) { return x[0]; }).join(", ") + ". These are real fixes, not suppressions." : true; } },
      { id: "bucket", text: "Fix the bucket: versioning, KMS encryption and a full public access block.", hints: ["CKV_AWS_21, CKV_AWS_145, CKV2_AWS_6: the three companion resources from DEV-303."],
        check: function (r) { var res = scanNow(r); var need = ["CKV_AWS_21", "CKV_AWS_145", "CKV2_AWS_6"].filter(function (id) { return status(res, id, "aws_s3_bucket") !== "PASSED"; }); return need.length ? "Still failing (or skipped): " + need.join(", ") + "." : true; } },
      { id: "zero", text: "Suppress each remaining check that doesn't apply, inside its resource, <b>with a reason</b>, until Checkov reports zero failed checks.", hints: ["#checkov:skip=CKV_AWS_260:reason ... inside the resource block. checkov -d . should exit 0."],
        check: function (r) { var e = lastCheckov(r); if (!e || e.failed) return "The last checkov run in ~/infra/web still has failed checks."; var res = scanNow(r), noReason = res.filter(function (x) { return x.result === "SKIPPED" && (!x.reason || x.reason === "No comment provided" || x.reason.length < 10); }); if (noReason.length) return "Give every suppression a real reason: " + noReason.map(function (x) { return x.id; }).join(", ") + "."; return res.filter(function (x) { return x.result === "FAILED"; }).length ? "The files changed since your last scan: run checkov again." : true; } },
      { id: "apply", text: "Apply the scanned configuration.", hints: ["terraform init && terraform apply -auto-approve"],
        check: function (r) { var i = H.find(r, "aws_instance", function () { return true; }); if (!i) return "Apply it: terraform init, terraform apply."; var g = H.find(r, "aws_security_group", function (x) { return x.name === "web"; }); if (IAC.sgAllows(IAC.aws(r.sys), [g.id], 22, "198.51.100.7")) return "The applied security group still allows SSH from anywhere."; return i.metadata_options[0].http_tokens === "required" && i.root_block_device[0].encrypted ? true : "The applied instance should have IMDSv2 required and an encrypted disk."; } },
      { id: "lint", text: "Make <code>~/ansible</code> pass <code>ansible-lint</code> by fixing the playbook (no <code># noqa</code>).", hints: ["Name every task, use ansible.builtin.* modules, true instead of yes, state: present, unarchive instead of curl | tar, a mode on the template."],
        check: function (r) { var pb = r.read(HOME + "/ansible/notes.yml") || ""; if (/noqa/.test(pb) || r.read(HOME + "/ansible/.ansible-lint") != null) return "Fix the findings instead of ignoring them."; return ran(r, /ansible-lint\b/, function (e) { return /Passed: 0 failure/.test(out(e)); }) ? true : "Run ansible-lint in ~/ansible until it passes."; } }
    ],
    solution: sol("cd ~/infra/web", "checkov -d . --compact", "checkov -d . --compact --quiet", { nano: "main.tf", text: SECURE_TF }, "checkov -d . --compact", "terraform init", "terraform apply -auto-approve",
      "cd ~/ansible", "ansible-lint", { nano: "notes.yml", text: LINT_FIXED }, "ansible-lint"),
    debrief: "<p>Checkov caught six real problems before they existed in AWS, and you fixed them in code. The rest are suppressed in the resources they apply to, each with a reason a reviewer can push back on, so the scan is green without being blind. The playbook lost its shell pipe, its unpinned <code>latest</code> and its unnamed tasks.</p><p>A scanner on a laptop is a habit; a scanner in the pipeline is a gate. Next: running Terraform from GitHub Actions without a single stored AWS key.</p>",
    realworld: "Checkov, tfsec (now part of Trivy: trivy config .), KICS and Terrascan are the common open-source scanners; OPA/Conftest lets you write your own policies. Most teams run one in pre-commit and in CI, with a baseline file for existing findings.",
    quiz: [
      { q: "When is suppressing a Checkov finding the right call?", options: ["When it's inconvenient", "When the check doesn't apply to this resource, and you write down why", "Never", "When the plan is too long"], answer: 1, why: "Suppressions are fine with a reason a reviewer can judge; unexplained ones hide risk." },
      { q: "Why does a pipeline care about Checkov's exit code?", options: ["It doesn't", "A non-zero exit (failed checks) fails the job, blocking the merge", "It prints colours", "It uploads results"], answer: 1, why: "That's what turns a report into a gate." },
      { q: "<code>shell: curl ... | tar xz</code> gets which ansible-lint findings?", options: ["None", "command-instead-of-module and risky-shell-pipe (and no-changed-when)", "Only name[missing]", "yaml[truthy]"], answer: 1, why: "unarchive does it idempotently; pipes hide failures without pipefail." }
    ]
  });

  /* ================================================================== DEV-309 Terraform in a pipeline */
